/**
 * Static GridStack callbacks for React — same pattern as Angular gsCreateNgComponents.
 * Dispatches via DOM `_gridComp` / `_gridItemRef` back-refs (no closure over per-grid state).
 */
import { GridStack, Utils } from "gridstack";
export function installGridStackReactCallbacks() {
    if (!GridStack.addRemoveCB) {
        GridStack.addRemoveCB = gsCreateReactComponents;
    }
    if (!GridStack.saveCB) {
        GridStack.saveCB = gsSaveAdditionalReactInfo;
    }
    if (!GridStack.updateCB) {
        GridStack.updateCB = gsUpdateReactComponents;
    }
}
/** @internal Walk up from `el` to find the nearest `_gridComp` back-ref. */
function nearestGridComp(el) {
    let node = el;
    while (node) {
        const comp = node._gridComp;
        if (comp)
            return comp;
        node = node.parentElement;
    }
    return undefined;
}
/** @internal */
export function gsCreateReactComponents(parent, w, add, isGrid) {
    if (add) {
        if (isGrid) {
            const opt = w;
            const classes = ["grid-stack"];
            if (opt.class)
                classes.push(...String(opt.class).split(" ").filter(Boolean));
            const el = Utils.createDiv(classes);
            // Inherit the host's _gridComp so nested-grid children can register portals.
            const inherited = nearestGridComp(parent);
            if (inherited)
                el._gridComp = inherited;
            parent?.appendChild(el);
            return el;
        }
        const gridHost = parent._gridComp;
        if (!gridHost)
            return undefined;
        const opt = w;
        const itemClasses = ["grid-stack-item"];
        if (opt.class)
            itemClasses.push(...String(opt.class).split(" ").filter(Boolean));
        const el = Utils.createDiv(itemClasses);
        Utils.createDiv(["grid-stack-item-content"], el);
        const id = opt.id != null ? String(opt.id) : undefined;
        if (id) {
            el._gridItemRef = { id, gridComp: gridHost };
            if (opt.component) {
                // Utils.lazyLoad checks opt.lazyLoad and grid.opts.lazyLoad with correct precedence.
                const lazy = Utils.lazyLoad(w);
                if (lazy) {
                    el._lazyObserver = new IntersectionObserver(([entry]) => {
                        if (entry.isIntersecting) {
                            el._lazyObserver?.disconnect();
                            delete el._lazyObserver;
                            gridHost.registerSyntheticItemId(id);
                        }
                    });
                    // Observe after GS sets position attributes (next frame).
                    setTimeout(() => el._lazyObserver?.observe(el));
                }
                else {
                    gridHost.registerSyntheticItemId(id);
                }
            }
        }
        if (opt.content != null && opt.content !== "") {
            const content = el.querySelector(".grid-stack-item-content");
            if (content)
                content.textContent = String(opt.content);
        }
        return el;
    }
    // Remove path
    const el = w.el;
    if (el?._lazyObserver) {
        el._lazyObserver.disconnect();
        delete el._lazyObserver;
    }
    if (el?._gridItemRef) {
        const { id, gridComp } = el._gridItemRef;
        gridComp.unregisterSyntheticItemId(id);
        delete el._gridItemRef;
    }
    el?.remove();
    return undefined;
}
export function gsSaveAdditionalReactInfo(node, w) {
    const n = node;
    const out = w;
    if (n.component != null)
        out.component = n.component;
    if (n.props != null)
        out.props = { ...n.props };
    // Strip runtime-only fields that must never appear in serialized output.
    delete out.visibleObservable;
    const el = node.el;
    const id = n.id != null ? String(n.id) : undefined;
    if (id && el?._gridItemRef?.gridComp?.mergeWidgetPropsForSave) {
        el._gridItemRef.gridComp.mergeWidgetPropsForSave(id, out);
    }
}
export function gsUpdateReactComponents(node) {
    const w = node;
    const el = node.el;
    const ref = el?._gridItemRef;
    if (!ref)
        return;
    const { id, gridComp } = ref;
    // Call registered deserialize fn so widget components can react to updated props.
    if (w.props)
        gridComp.deserializeWidget?.(id, w);
    gridComp.requestUpdate?.();
}
